import{bt as e,n as t,ot as n,st as r}from"./chunks/framework.CxhjsvYc.js";var i=JSON.parse(`{"title":"Age-based FD eligibility","description":"Bank-specific senior and minor fixed-deposit age rules, verified product rates, catalogue fields and current coverage limits.","frontmatter":{"title":"Age-based FD eligibility","description":"Bank-specific senior and minor fixed-deposit age rules, verified product rates, catalogue fields and current coverage limits.","head":[["link",{"rel":"canonical","href":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/reference/fd-eligibility.html"}],["meta",{"property":"og:title","content":"Age-based FD eligibility | FD Cal Documentation"}],["meta",{"property":"og:description","content":"Bank-specific senior and minor fixed-deposit age rules, verified product rates, catalogue fields and current coverage limits."}],["meta",{"property":"og:url","content":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/reference/fd-eligibility.html"}],["meta",{"name":"twitter:title","content":"Age-based FD eligibility | FD Cal Documentation"}],["meta",{"name":"twitter:description","content":"Bank-specific senior and minor fixed-deposit age rules, verified product rates, catalogue fields and current coverage limits."}]]},"headers":[],"relativePath":"reference/fd-eligibility.md","filePath":"reference/fd-eligibility.md","lastUpdated":1794147699000}`),a={name:`reference/fd-eligibility.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<h1 id="age-based-fd-eligibility" tabindex="-1">Age-based FD eligibility <a class="header-anchor" href="#age-based-fd-eligibility" aria-label="Permalink to “Age-based FD eligibility”">​</a></h1><p>Some Sri Lankan banks publish separate fixed-deposit products or rates for senior customers and minors. These are <strong>product eligibility rules</strong>, not universal age rules: each bank defines its own cutoff, boundary wording, minimum deposit, permitted tenure and account-opening requirements.</p><h2 id="how-fd-cal-represents-age-eligibility" tabindex="-1">How FD Cal represents age eligibility <a class="header-anchor" href="#how-fd-cal-represents-age-eligibility" aria-label="Permalink to “How FD Cal represents age eligibility”">​</a></h2><p>The bank product CSVs can record:</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>customer_segment</code></td><td><code>general</code>, <code>senior</code> or <code>minor</code></td></tr><tr><td><code>min_age</code>, <code>max_age</code></td><td>Published lower and upper age bounds; blank means the bank did not publish that bound in the source we verified</td></tr><tr><td><code>min_age_inclusive</code>, <code>max_age_inclusive</code></td><td>Whether the corresponding boundary is inclusive</td></tr><tr><td><code>guardian_required</code></td><td>Whether the source explicitly requires a parent or guardian</td></tr></tbody></table><p>The browser exposes <strong>Include senior citizen FDs</strong> and <strong>Include child / minor FDs</strong> switches. They default off, preserve all general products, and add only the selected age-segment products. The switches do not collect a date of birth or claim that a particular person qualifies. For products actually booked by a simulation, the standalone report displays the age bounds, inclusive/exclusive boundary and guardian requirement recorded in the catalogue. These conditions remain informational and must be confirmed with the bank. A bank&#39;s wording such as “over 60” is stored as a strict lower bound, not silently rounded to “60+”.</p><h2 id="verified-products-currently-represented-in-the-rate-catalogue" tabindex="-1">Verified products currently represented in the rate catalogue <a class="header-anchor" href="#verified-products-currently-represented-in-the-rate-catalogue" aria-label="Permalink to “Verified products currently represented in the rate catalogue”">​</a></h2><table tabindex="0"><thead><tr><th>Bank / product</th><th>Published age rule</th><th>Dataset coverage</th><th>Source</th></tr></thead><tbody><tr><td>SANASA Development Bank — Upahara FD</td><td>Over 55 years</td><td>Maturity rates for 1, 3, 6, 12, 13, 24, 36, 48, 60 and 120 months; monthly rates for 12, 13, 24, 36, 48, 60 and 120 months; minimum LKR 10,000</td><td><a href="https://www.sdb.lk/en/rates?tableid=4" target="_blank" rel="noreferrer">Official rates</a></td></tr><tr><td>SANASA Development Bank — Minor FD</td><td>Sri Lankan citizens below 18, with a guardian</td><td>Maturity rates for 12, 24, 36, 48, 60 and 120 months; minimum LKR 10,000</td><td><a href="https://www.sdb.lk/en/rates?tableid=4" target="_blank" rel="noreferrer">Official rates</a> · <a href="https://www.sdb.lk/images/pdf/kfd/sdb-minor-fd-en.pdf" target="_blank" rel="noreferrer">Minor FD KFD</a></td></tr><tr><td>Seylan Bank — Senior Citizens FD</td><td>Over 60 years</td><td>Published maturity rates for 1, 48 and 60 months, where the product-specific LKR 100,000 minimum is stated. Other tenures are held back because the reviewed schedule does not give a matching minimum-deposit value</td><td><a href="https://www.seylan.lk/interest-rates?url=senior-citizen-fds" target="_blank" rel="noreferrer">Official rate schedule</a></td></tr></tbody></table><p>Rates retain their source effective dates and minimum-deposit values in the CSV rows. They should be checked against the linked bank schedule before an actual placement.</p><h2 id="identified-products-not-yet-added-as-simulated-rate-rows" tabindex="-1">Identified products not yet added as simulated rate rows <a class="header-anchor" href="#identified-products-not-yet-added-as-simulated-rate-rows" aria-label="Permalink to “Identified products not yet added as simulated rate rows”">​</a></h2><ul><li><strong>People&#39;s Bank senior / Parinatha FDs:</strong> the term-deposit page lists a senior FD for customers over 55 (minimum LKR 100,000; 12/24 months) and a special senior product for customers over 60 (minimum LKR 5,000; cumulative cap LKR 1.5 million; interest exempt from income tax). The rate page&#39;s Parinatha bands show a LKR 5,000 minimum, so the rate/product mapping is unresolved. The over-60 cap and tax treatment are also not enforced by the simulator. These rates remain in the research ledger, not the optimizer. See <a href="https://www.peoplesbank.lk/term-deposite/" target="_blank" rel="noreferrer">term-deposit terms</a> and <a href="https://peoplesbank.lk/interest-rates/" target="_blank" rel="noreferrer">rate schedule</a>.</li><li><strong><a href="https://www.peoplesbank.lk/term-deposite/" target="_blank" rel="noreferrer">People&#39;s Bank Minor FD</a>:</strong> the bank says the product is for children up to 18 years, can be opened by a parent or guardian, and pays 0.5 percentage points above normal FD rates. The product page does not clearly publish a separate minimum deposit or complete product-specific rate/tenure table. We are not copying the adult minimum or deriving simulated rates until the minor product&#39;s terms are confirmed.</li><li><strong><a href="https://www.rdb.lk/interest-rates/" target="_blank" rel="noreferrer">RDB Senior Citizen FD</a>:</strong> the official schedule states over 60 and publishes one-year maturity and monthly rates, but does not state a senior-product minimum. The general FD minimum is not borrowed; the senior option remains in the research ledger only.</li><li><strong><a href="https://www.nationstrust.com/images/pdf/key-facts-doc/kfd-senior-citizen-savings-en.pdf" target="_blank" rel="noreferrer">Nations Trust Bank — Nations Prabuddha Senior Citizen FD</a>:</strong> the official key facts document confirms an over-60 product with 12–60 month tenures and monthly or maturity payout. Current senior-specific rates are not yet confirmed.</li><li><strong><a href="https://www.sampath.lk/api/uploads/senior_citizen_opening_special_fd_accounts_d3405c3b1a_a20fdec085.pdf" target="_blank" rel="noreferrer">Sampath Bank — Sanhinda senior special FD</a>:</strong> the official declaration confirms resident Sri Lankan citizens over 60 and a scheme-wide LKR 1.5 million deposit cap across banks. Current product rates and full terms are not yet confirmed.</li><li><strong><a href="https://www.hdfc.lk/fd-%26-investments/vishrama-udana-fixed-deposit" target="_blank" rel="noreferrer">HDFC Vishrama Udana</a></strong> and <strong><a href="https://www.smib.lk/en/investments/senior-citizen-fixed-deposits" target="_blank" rel="noreferrer">SMIB Senior Citizen FD</a>:</strong> official product pages state an over-60 eligibility rule. Their senior product rates are not added here until a current, matching rate schedule is verified.</li></ul><h2 id="research-ledger" tabindex="-1">Research ledger <a class="header-anchor" href="#research-ledger" aria-label="Permalink to “Research ledger”">​</a></h2><p>The machine-readable research ledger includes products whose eligibility is known even when a current matching rate or minimum deposit is not yet safe to simulate: <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/main/data/fd_options/age_eligibility.csv" target="_blank" rel="noreferrer">age_eligibility.csv</a>. Its <code>research_status</code> distinguishes catalogue-ready entries from incomplete or conflicting evidence.</p><h2 id="data-policy" tabindex="-1">Data policy <a class="header-anchor" href="#data-policy" aria-label="Permalink to “Data policy”">​</a></h2><p>No age threshold is inferred from a product name, tax treatment, general account eligibility or another bank&#39;s rules. No dummy rates are inserted. If a bank publishes a rate but omits an age cutoff, or publishes eligibility but not a current rate, that information remains documented as incomplete rather than becoming an optimisable product.</p><p>Age eligibility is evaluated at the product/account-opening point where the bank&#39;s terms say so. Where the bank does not specify the exact reference date or boundary, the catalogue must retain that uncertainty rather than invent a rule.</p>`,16)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};